const issues = [];

const email = String($json.email || '').trim();
const projectBrief = String($json.project_brief || '').trim();

if (!String($json.full_name || '').trim()) {
  issues.push('Full Name');
}

if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  issues.push('Valid Email Address');
}

if (!String($json.company_name || '').trim()) {
  issues.push('Company Name');
}

if (!String($json.industry || '').trim()) {
  issues.push('Industry');
}

if (!String($json.required_service || '').trim()) {
  issues.push('Required Service');
}

if (projectBrief.length < 20) {
  issues.push('Project Brief (minimum 20 characters)');
}

if (!String($json.budget_range || '').trim()) {
  issues.push('Budget Range');
}

if (!String($json.expected_timeline || '').trim()) {
  issues.push('Expected Timeline');
}

if (!String($json.phone_number || '').trim()) {
  issues.push('Phone Number');
}

return {
  json: {
    ...$json,
    validation_status: 'incomplete',
    validation_issues: issues,
    validation_issues_text: issues.join(', ')
  }
};

