const input = $json;

function findAnalysis(value) {
  if (!value) return null;

  if (
    typeof value === 'object' &&
    !Array.isArray(value) &&
    value.client_summary !== undefined &&
    value.service_category !== undefined
  ) {
    return value;
  }

  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      const result = findAnalysis(parsed);
      if (result) return result;
    } catch {}
  }

  if (Array.isArray(value)) {
    for (const item of value) {
      const result = findAnalysis(item);
      if (result) return result;
    }
  }

  if (typeof value === 'object') {
    for (const item of Object.values(value)) {
      const result = findAnalysis(item);
      if (result) return result;
    }
  }

  return null;
}

const analysis = findAnalysis(input);

if (!analysis) {
  throw new Error('Structured AI analysis could not be found.');
}

const client = $('Normalize Client Data').item.json;
const lead = $('Create Lead in Supabase').item.json;

return {
  json: {
    lead_id: lead.id,

    full_name: client.full_name,
    email: client.email,
    company_name: client.company_name,
    industry: client.industry,
    required_service: client.required_service,
    project_brief: client.project_brief,
    budget_range: client.budget_range,
    expected_timeline: client.expected_timeline,
    phone_number: client.phone_number,

    client_summary: analysis.client_summary,
    service_category: analysis.service_category,
    complexity: analysis.complexity,
    priority: analysis.priority,
    missing_information: analysis.missing_information || [],
    risk_flags: analysis.risk_flags || [],
    recommended_next_step: analysis.recommended_next_step
  }
};

let score = 0;

// ---------- Budget: Max 40 ----------
const budget = String($json.budget_range || '')
  .toLowerCase()
  .replace(/[$,\s]/g, '')
  .replace(/[–—]/g, '-');

if (budget.includes('5000+')) {
  score += 40;
} else if (budget.includes('3000-5000')) {
  score += 35;
} else if (budget.includes('1000-3000')) {
  score += 25;
} else if (budget.includes('500-1000')) {
  score += 12;
} else {
  score += 5;
}

// ---------- Timeline: Max 10 ----------
const timeline = String($json.expected_timeline || '').toLowerCase();

if (timeline.includes('asap')) {
  score += 10;
} else if (timeline.includes('1-2')) {
  score += 8;
} else if (timeline.includes('2-3') || timeline.includes('2-4')) {
  score += 7;
} else if (timeline.includes('1-3')) {
  score += 5;
} else if (timeline.includes('flexible')) {
  score += 6;
}

// ---------- Project Brief: Max 15 ----------
const briefLength = String($json.project_brief || '').trim().length;

if (briefLength >= 120) {
  score += 15;
} else if (briefLength >= 60) {
  score += 12;
} else if (briefLength >= 20) {
  score += 8;
}

// ---------- Service clarity: Max 10 ----------
if (String($json.required_service || '').trim()) {
  score += 10;
}

// ---------- Business information: Max 10 ----------
if (
  String($json.company_name || '').trim() &&
  String($json.industry || '').trim()
) {
  score += 10;
}

// ---------- AI Quality / Risk: Max 15 ----------
const missing = Array.isArray($json.missing_information)
  ? $json.missing_information.length
  : 0;

const risks = Array.isArray($json.risk_flags)
  ? $json.risk_flags.length
  : 0;

let qualityScore = 15;

qualityScore -= missing * 3;
qualityScore -= risks * 3;

qualityScore = Math.max(0, qualityScore);

score += qualityScore;

// ---------- Qualification ----------
let qualification;

if (score >= 75) {
  qualification = 'hot';
} else if (score >= 50) {
  qualification = 'warm';
} else {
  qualification = 'low_fit';
}

return {
  json: {
    ...$json,
    qualification_score: score,
    qualification
  }
};

